-- 03 Formula registry (metadata-driven engine). Seeded by sql/seed/ref_formula_seed.sql (generated by tools/formula_seed.py) from
-- dam_safety.formulas.registry.REGISTRY; every row carries its source citation and test vectors.
USE CATALOG IDENTIFIER(:catalog);

CREATE TABLE IF NOT EXISTS ref.formula (
  formula_id      STRING NOT NULL,
  formula_version STRING NOT NULL,
  reading_type    STRING NOT NULL,
  output_unit     STRING NOT NULL,
  description     STRING,
  source_citation ARRAY<STRING> NOT NULL,
  test_vectors    STRING COMMENT 'JSON worked examples with expected values + source',
  verified        BOOLEAN NOT NULL,
  code_ref        STRING COMMENT 'python import path + git sha',
  registered_ts   TIMESTAMP,
  CONSTRAINT pk_formula PRIMARY KEY (formula_id, formula_version)
);
